import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
export interface ExpiryDto {
  id?: number;
  productId: number,
  productName: string; 
  preservationDate: string,
  validity: number,
  expiryDate: string,
  strength: number,
  de: number,
  da: number,
  db: number,
  dc: number
}

@Injectable({
  providedIn: 'root'
})
export class ExpiryService {
  private apiUrl = `${environment.apiUrl}/qc_expiry`; 
  constructor(private http: HttpClient) {}

  getAllProducts(): Observable<ExpiryDto[]> {
    return this.http.get<ExpiryDto[]>(this.apiUrl);
  }

  getProductByID(id: number): Observable<ExpiryDto> {
    return this.http.get<ExpiryDto>(`${this.apiUrl}/${id}`)
  }

  addProduct(product: ExpiryDto): Observable<ExpiryDto> {
  return this.http.post<ExpiryDto>(`${this.apiUrl}/create`, product);
}

updateProduct(id: number, product: ExpiryDto): Observable<ExpiryDto> {
  return this.http.put<ExpiryDto>(`${this.apiUrl}/replace/${id}`, product);
}

deleteProduct(id: number): Observable<void> {
  return this.http.delete<void>(`${this.apiUrl}/${id}`);
}
}
